type Membership = { organization_id: string; organization_name?: string; organization_slug?: string; organization_status?: 'setup'|'active'|'suspended'; role_codes: string[] };
export type Session = { accessToken: string; user: { displayName: string; email: string | null; platformAdmin?: boolean; memberships: Membership[] } };
type TicketTag = { id: string; name: string; color: string };
export type Ticket = { id: string; ticket_number: number; title: string; description?: string; status: string; priority: string; created_at: string; updated_at?: string; last_activity_at?: string; assigned_to_user_id?: string; assignee_display_name?: string; requester_display_name?: string; department_name?: string; category_name?: string; location_name?: string; resolution_due_at?: string; warning_at?: string; breached_at?: string; custom_fields?: {key:string;label:string;value:unknown}[]; tags?: TicketTag[] };
type Message = { id: string; author_display_name: string; body: string; created_at: string };
export type Actor = { session: Session; organizationId: string; membership: Membership };
const api = import.meta.env.VITE_API_URL ?? '/api/v1';
const savedSession = () => { try { return JSON.parse(sessionStorage.getItem('jupiter.session') ?? 'null') as Session | null; } catch { return null; } };

async function renewSession() {
  const response = await fetch(`${api}/auth/refresh`, { method: 'POST', credentials: 'include' });
  if (!response.ok) return null;
  const next = await response.json() as Session;
  sessionStorage.setItem('jupiter.session', JSON.stringify(next));
  window.dispatchEvent(new Event('jupiter:session-refreshed'));
  return next;
}

export async function request(path: string, session: Session, organizationId: string, init?: RequestInit) {
  const send = (accessToken: string) => fetch(`${api}${path}`, { ...init, credentials: 'include', headers: { 'content-type': 'application/json', authorization: `Bearer ${accessToken}`, 'x-organization-id': organizationId, ...(init?.headers ?? {}) } });
  let response = await send(session.accessToken);
  if (response.status === 401) {
    const next = await renewSession();
    if (next) response = await send(next.accessToken);
    else { sessionStorage.removeItem('jupiter.session'); window.dispatchEvent(new Event('jupiter:session-expired')); }
  }
  if (!response.ok) {
    const payload = await response.json().catch(() => ({ message: 'خطا در ارتباط با سرور' }));
    throw new Error(response.status === 401 ? 'نشست شما پایان یافته است؛ دوباره وارد شوید.' : payload.message ?? 'خطا در ارتباط با سرور');
  }
  return response.status === 204 ? undefined : response.json();
}

export function App() {
  const [session, setSession] = useState<Session | null>(savedSession);
  const [organizationId, setOrganizationId] = useState(session?.user.memberships[0]?.organization_id ?? '');
  useEffect(() => { void fetch(`${api}/appearance`).then((response) => response.ok ? response.json() : null).then((value: PlatformAppearanceValue | null) => { if (value) applyPlatformAppearance(value); }).catch(() => undefined); }, []);
  const login = (value: Session) => { sessionStorage.setItem('jupiter.session', JSON.stringify(value)); setSession(value); setOrganizationId(value.user.memberships[0]?.organization_id ?? ''); };
  const logout = () => { void fetch(`${api}/auth/logout`, { method: 'POST', credentials: 'include' }); sessionStorage.removeItem('jupiter.session'); setSession(null); setOrganizationId(''); };
  useEffect(() => { const update = () => setSession(savedSession()); const expire = () => { setSession(null); setOrganizationId(''); }; window.addEventListener('jupiter:session-refreshed', update); window.addEventListener('jupiter:session-expired', expire); return () => { window.removeEventListener('jupiter:session-refreshed', update); window.removeEventListener('jupiter:session-expired', expire); }; }, []);
  if (!session) return <PublicEntry onSession={login} />;
  const match = /^\/o\/([a-z0-9-]{3,63})(\/.*)?$/.exec(window.location.pathname);
  const requestedSlug = match?.[1];
  const membership = requestedSlug ? session.user.memberships.find((item) => item.organization_slug === requestedSlug) : session.user.memberships.find((item) => item.organization_id === organizationId) ?? session.user.memberships[0];
  if (window.location.pathname.startsWith('/platform') && session.user.platformAdmin) return <BrowserRouter><main className="portal" dir="rtl"><header><div><p className="eyebrow">JUPITER / مدیر پلتفرم</p><h1>مدیریت پلتفرم</h1></div><button className="secondary" onClick={logout}>خروج</button></header><PlatformAdministration actor={{ session, organizationId: membership?.organization_id ?? '', membership: membership ?? { organization_id: '', role_codes: [] } }} /></main></BrowserRouter>;
  if (!requestedSlug && membership && session.user.memberships.length === 1 && membership.organization_slug && !window.location.pathname.startsWith('/platform')) { window.location.replace(`/o/${membership.organization_slug}${window.location.pathname === '/' ? '' : window.location.pathname}`); return null; }
  if (!requestedSlug && session.user.memberships.length > 1 && !window.location.pathname.startsWith('/platform')) return <OrganizationChooser memberships={session.user.memberships}/>;
  if (!membership && session.user.platformAdmin) return <BrowserRouter><main className="portal" dir="rtl"><header><div><p className="eyebrow">JUPITER / مدیر پلتفرم</p><h1>مدیریت پلتفرم</h1></div><button className="secondary" onClick={logout}>خروج</button></header><PlatformAdministration actor={{ session, organizationId: '', membership: { organization_id: '', role_codes: [] } }} /></main></BrowserRouter>;
  if (!membership) return <NoOrganization session={session} onLogout={logout} />;
  const selectOrganization=(id:string)=>{const target=session.user.memberships.find((item)=>item.organization_id===id);if(target?.organization_slug) window.location.assign(`/o/${target.organization_slug}`);};
  const actor={ session, organizationId: membership.organization_id, membership };
  if (match?.[2] === '/help') return <BrowserRouter basename={`/o/${membership.organization_slug ?? ''}`}><ProductHelpStandalone actor={actor}/></BrowserRouter>;
  return <BrowserRouter basename={`/o/${membership.organization_slug ?? ''}`}>{membership.organization_status==='setup' ? <SetupWorkspace actor={actor} onLogout={logout}/> : <ProductShell actor={actor} onOrganization={selectOrganization} onLogout={logout} />}</BrowserRouter>;
}

function ProductHelpStandalone({ actor }: { actor:Actor }) { return <main className="app-main help-standalone" dir="rtl"><header className="app-header"><div className="page-context"><p className="eyebrow">JUPITER / راهنمای محصول</p><p className="shell-title">مرکز خدمات پشتیبانی</p></div><Link className="ui-button secondary" to="/">بازگشت به سامانه</Link></header><HelpCenter actor={actor}/></main>; }

function OrganizationChooser({memberships}:{memberships:Membership[]}) { return <main className="login-page" dir="rtl"><section className="login-card"><div><p className="eyebrow">سازمان</p><h1>یک سازمان را انتخاب کنید</h1><p>برای ادامه، فضای کاری موردنظر را باز کنید.</p></div>{memberships.map((membership)=><a className="ui-button secondary" key={membership.organization_id} href={`/o/${membership.organization_slug}`}>{membership.organization_name ?? 'سازمان'}</a>)}</section></main>; }

function SetupWorkspace({actor,onLogout}:{actor:Actor;onLogout:()=>void}) { const [state,setState]=useState<{name:string;slug:string;isOwner:boolean;settingsReady:boolean;categories:number;status:string}|null>(null);const [notice,setNotice]=useState('');const load=()=>request('/admin/tenant-setup',actor.session,actor.organizationId).then(setState).catch(cause=>setNotice(cause instanceof Error?cause.message:'دریافت وضعیت راه‌اندازی ناموفق بود.'));useEffect(()=>{void load();},[actor.organizationId]);const complete=async()=>{try{await request('/admin/tenant-setup/complete',actor.session,actor.organizationId,{method:'POST'});window.location.reload();}catch(cause){setNotice(cause instanceof Error?cause.message:'تکمیل راه‌اندازی ناموفق بود.');}};return <main className="setup-workspace" dir="rtl"><section className="setup-card"><div><p className="eyebrow">راه‌اندازی سازمان</p><h1>{state?.name??actor.membership.organization_name??'سازمان شما'}</h1><p>این فضای کاری پس از تکمیل تنظیمات اولیه فعال می‌شود.</p></div>{notice&&<p className="error" role="alert">{notice}</p>}{state?.isOwner?<><ol className="setup-checklist"><li className={state.settingsReady?'complete':''}>تنظیمات سازمان را در بخش مدیریت بررسی و ذخیره کنید.</li><li className={state.categories>0?'complete':''}>حداقل یک دسته‌بندی خدمات بسازید یا الگوی کاتالوگ را نصب کنید.</li><li>پس از تکمیل دو مورد بالا، سازمان را فعال کنید.</li></ol><div className="inline-actions"><Link className="ui-button secondary" to="/admin/settings">تنظیمات سازمان</Link><Link className="ui-button secondary" to="/admin/catalog">کاتالوگ خدمات</Link><button type="button" onClick={()=>void complete()} disabled={!state.settingsReady||state.categories<1}>فعال‌سازی سازمان</button></div></>:<p className="hint">راه‌اندازی توسط مالک سازمان در حال انجام است. پس از فعال‌سازی، فضای کاری در دسترس خواهد بود.</p>}<button type="button" className="secondary" onClick={onLogout}>خروج</button></section></main>; }

function PublicEntry({ onSession }: { onSession: (session: Session) => void }) {
  const [mode, setMode] = useState<'login' | 'register' | 'verify'>(() => new URLSearchParams(window.location.search).get('verify') ? 'verify' : 'login');
  const token = new URLSearchParams(window.location.search).get('verify') ?? '';
  const finishVerification = () => { window.history.replaceState({}, '', window.location.pathname); setMode('login'); };
  if (mode === 'register') return <PublicRegistration onSession={onSession} onBack={() => setMode('login')} />;
  if (mode === 'verify' && token) return <EmailVerification token={token} onVerified={finishVerification} onBack={() => setMode('login')} />;
  return <Login onSession={onSession} onRegister={() => setMode('register')} />;
}

function Login({ onSession, onRegister }: { onSession: (session: Session) => void; onRegister: () => void }) {
  const [identifier, setIdentifier] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [visible, setVisible] = useState(false);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const response = await fetch(`${api}/auth/login`, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ identifier, email: identifier.includes('@') ? identifier : undefined, password }) }); if (!response.ok) throw new Error(response.status===429?'تعداد تلاش‌های ورود زیاد است؛ یک دقیقه دیگر دوباره امتحان کنید.':'اطلاعات ورود صحیح نیست.'); onSession(await response.json()); } catch (cause) { setError(cause instanceof Error?cause.message:'امکان ورود وجود ندارد.'); } finally { setBusy(false); } }
  return <main className="login-page"><section className="login-card"><BrandLogo/><div><p className="eyebrow">ورود امن</p><h1>به ژوپیتر خوش آمدید</h1><p>برای پیگیری و مدیریت خدمات سازمانی وارد شوید.</p></div><form onSubmit={submit}><label>ایمیل یا نام کاربری<input value={identifier} onChange={(e) => setIdentifier(e.target.value)} autoComplete="username" required /></label><label>رمز عبور<span className="password-input"><input value={password} onChange={(e) => setPassword(e.target.value)} type={visible?'text':'password'} autoComplete="current-password" required/><IconButton type="button" label={visible?'پنهان‌کردن رمز':'نمایش رمز'} onClick={()=>setVisible(!visible)}>{visible?<EyeOff size={18}/>:<Eye size={18}/>}</IconButton></span></label>{error && <p className="error" role="alert">{error}</p>}<Button loading={busy}>ورود به سامانه</Button><button type="button" className="login-register-link" onClick={onRegister}>ثبت درخواست سازمان</button></form></section></main>;
}

function NoOrganization({ session, onLogout }: { session: Session; onLogout: () => void }) { return <ApplicantWorkspace session={session} request={request} onLogout={onLogout} />; }

function ProductShell({ actor, onOrganization, onLogout }: { actor: Actor; onOrganization: (id: string) => void; onLogout: () => void }) {
  const isAdmin = actor.membership.role_codes.includes('ORG_ADMIN');
  const staff = actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR', 'EXPERT'].includes(role));
  const reportViewer = actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR'].includes(role));
  const roleTitle = useMemo(() => actor.membership.role_codes.map((role) => ({ REQUESTER: 'درخواست‌کننده', EXPERT: 'کارشناس', SUPERVISOR: 'سرپرست', ORG_ADMIN: 'مدیر سازمان', ORG_OWNER: 'مالک سازمان' }[role] ?? role)).join('، '), [actor.membership]);
  const nav = [{ to: '/', label: 'داشبورد', icon:LayoutDashboard }, { to: '/tickets', label: 'تیکت‌ها', icon:ClipboardList }, { to: '/knowledge', label: 'دانش‌نامه', icon:BookOpen }, { to: '/help', label: 'راهنمای محصول', icon:BookOpen }, { to: '/reports', label: 'گزارش‌ها', icon:FileBarChart, visible: reportViewer }, { to: '/admin', label: 'مدیریت سازمان', icon:Settings, visible: isAdmin }, { to: '/platform', label: 'مدیریت پلتفرم', icon:ShieldCheck, visible: actor.session.user.platformAdmin }];
  const [mobileOpen,setMobileOpen]=useState(false); const [collapsed,setCollapsed]=useState(false); const drawerRef = useRef<HTMLElement>(null); const visibleNav=nav.filter(item=>item.visible!==false);
  const organizationCount = actor.session.user.memberships.length;
  const organizationName = actor.membership.organization_name ?? 'سازمان';
  const closeMobileMenu = () => { setMobileOpen(false); window.setTimeout(() => document.querySelector<HTMLButtonElement>('.mobile-menu-trigger')?.focus(), 0); };
  useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape' && mobileOpen)closeMobileMenu();};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[mobileOpen]);
  useEffect(() => { if (mobileOpen) window.setTimeout(() => drawerRef.current?.querySelector<HTMLElement>('button, a')?.focus(), 0); }, [mobileOpen]);
  useEffect(() => { void request('/admin/branding', actor.session, actor.organizationId).then((value: { logo_url: string | null }) => window.dispatchEvent(new CustomEvent('jupiter:brand-logo-updated', { detail: { logoUrl: value.logo_url } }))).catch(() => undefined); }, [actor.organizationId, actor.session.accessToken]);
  const links=(mobile=false)=><nav aria-label="ناوبری اصلی">{visibleNav.map(({to,label,icon:Icon})=>to==='/help'?<a key={to} href={`/o/${actor.membership.organization_slug ?? ''}/help`} aria-label={!mobile && collapsed ? label : undefined} title={!mobile && collapsed ? label : undefined} onClick={()=>mobile&&closeMobileMenu()}><Icon size={18}/><span>{label}</span></a>:<NavLink key={to} to={to} end={to==='/'} aria-label={!mobile && collapsed ? label : undefined} title={!mobile && collapsed ? label : undefined} onClick={()=>mobile&&closeMobileMenu()}><Icon size={18}/><span>{label}</span></NavLink>)}</nav>;
  return <div className={`app-shell ${collapsed?'sidebar-collapsed':''}`} dir="rtl"><a className="skip-link" href="#main-content">پرش به محتوای اصلی</a><aside className="app-sidebar"><div className="brand"><BrandLogo compact={collapsed}/><IconButton label={collapsed?'بازکردن ناوبری':'جمع‌کردن ناوبری'} onClick={()=>setCollapsed(!collapsed)}><ChevronLeft size={18}/></IconButton></div>{links()}<div className="sidebar-footer"><CircleUserRound size={18}/><span>{collapsed?'':roleTitle}</span></div></aside>{mobileOpen&&<><button className="drawer-backdrop" aria-label="بستن منو" onClick={closeMobileMenu}/><aside ref={drawerRef} className="mobile-drawer" role="dialog" aria-modal="true" aria-label="منوی اصلی"><div><BrandLogo/><IconButton label="بستن منو" onClick={closeMobileMenu}><X/></IconButton></div>{links(true)}</aside></>}<main id="main-content" className="app-main"><header className="app-header"><div className="mobile-only"><IconButton className="mobile-menu-trigger" label="بازکردن منو" onClick={()=>setMobileOpen(true)}><Menu/></IconButton><BrandLogo compact/></div><div className="page-context"><p className="eyebrow">JUPITER / {actor.session.user.platformAdmin ? 'پلتفرم' : 'سازمان'} · {roleTitle}</p><p className="shell-title">مرکز خدمات پشتیبانی</p></div><div className="header-actions"><GlobalSearch actor={actor}/><NotificationCenter actor={actor}/><div className="account-controls">{organizationCount > 1 ? <select aria-label="انتخاب سازمان" value={actor.organizationId} onChange={(e) => onOrganization(e.target.value)}>{actor.session.user.memberships.map((item) => <option key={item.organization_id} value={item.organization_id}>{item.organization_name ?? 'سازمان'}</option>)}</select> : <p className="organization-context" title={organizationName}><span>سازمان</span><strong>{organizationName}</strong></p>}<AccountMenu actor={actor} onLogout={onLogout}/></div></div></header><Routes><Route path="/" element={<DashboardHome actor={actor} staff={staff} />} /><Route path="/tickets/*" element={<TicketWorkspace actor={actor} staff={staff} />} /><Route path="/knowledge" element={<KnowledgeSearch actor={actor} />} /><Route path="/reports" element={reportViewer ? <ReportsPanel actor={actor} /> : <Navigate to="/" replace />} /><Route path="/admin/*" element={isAdmin ? <AdminPage actor={actor} /> : <Navigate to="/" replace />} /><Route path="/platform" element={actor.session.user.platformAdmin ? <PlatformAdministration actor={actor} /> : <Navigate to="/" replace />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></main></div>;
}

function useDismissiblePopover() { const ref=useRef<HTMLDetailsElement>(null); const [open,setOpen]=useState(false); useEffect(()=>{const dismiss=(event:PointerEvent)=>{if(ref.current&&!ref.current.contains(event.target as Node))setOpen(false);};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false);};document.addEventListener('pointerdown',dismiss);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',dismiss);document.removeEventListener('keydown',escape);};},[]);return {ref,open,setOpen}; }

function NotificationCenter({actor}:{actor:Actor}) { const storage=`jupiter.notifications.${actor.organizationId}`; const [items,setItems]=useState<{type:string;ticketId:string}[]>(()=>{try{return JSON.parse(localStorage.getItem(storage)??'[]')}catch{return[]}}); const [enabled,setEnabled]=useState(true); const {ref,open,setOpen}=useDismissiblePopover(); const notificationLabel:Record<string,string>={ 'ticket.message_posted':'پیام جدید ثبت شد', 'ticket.internal_note_added':'یادداشت داخلی ثبت شد', 'ticket.status_changed':'وضعیت تیکت تغییر کرد', 'ticket.assigned':'مسئول تیکت تعیین شد', 'ticket.sla_warning':'هشدار نزدیک شدن به SLA', 'ticket.sla_breached':'SLA تیکت نقض شد', 'ticket.email_received':'تیکت از ایمیل دریافت شد' }; useEffect(()=>{try{localStorage.setItem(storage,JSON.stringify(items))}catch{/* storage is an enhancement only */}},[items,storage]); useEffect(()=>{request('/sla/preferences',actor.session,actor.organizationId).then((value:{in_app_enabled:boolean})=>setEnabled(value.in_app_enabled)).catch(()=>undefined);request('/notifications',actor.session,actor.organizationId).then((rows:{event_type:string;ticket_id:string}[])=>setItems(rows.map(row=>({type:row.event_type,ticketId:row.ticket_id})))).catch(()=>undefined);const controller=new AbortController(); const listen=async()=>{try{const response=await fetch(`${api}/notifications/events`,{headers:{authorization:`Bearer ${actor.session.accessToken}`,'x-organization-id':actor.organizationId},signal:controller.signal});if(!response.body)return;const reader=response.body.getReader();const decoder=new TextDecoder();let pending='';while(!controller.signal.aborted){const part=await reader.read();if(part.done)break;pending+=decoder.decode(part.value,{stream:true});const events=pending.split('\n\n');pending=events.pop()??'';for(const event of events){const data=event.split('\n').find(line=>line.startsWith('data: '))?.slice(6);if(data)try{const notice=JSON.parse(data) as {type:string;ticketId:string};setItems(current=>[notice,...current].slice(0,20));}catch{/* ignored malformed SSE */}}}}catch{/* Stream reconnects on the next page load; ticket work remains available. */}};void listen();return()=>controller.abort();},[actor.organizationId,actor.session.accessToken]); const toggle=async()=>{const next=!enabled;await request('/sla/preferences',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({inAppEnabled:next})});setEnabled(next);}; return <details ref={ref} className="notifications" open={open} onToggle={event=>setOpen(event.currentTarget.open)}><summary aria-label="اعلان‌ها" title="اعلان‌ها"><Bell size={19}/><span className="sr-only">اعلان‌ها</span>{items.length>0&&<b>{items.length}</b>}</summary><div>{items.length?items.map((item,index)=><p key={`${item.ticketId}-${index}`}>{notificationLabel[item.type]??'رویداد جدید برای تیکت'} · تیکت</p>):<p>اعلان جدیدی ندارید.</p>}<button className="secondary" onClick={()=>setItems([])}>پاک‌کردن</button><label><input type="checkbox" checked={enabled} onChange={()=>toggle().catch(()=>undefined)}/> اعلان درون‌برنامه‌ای</label></div></details>; }

function GlobalSearch({actor}:{actor:Actor}) { const [q,setQ]=useState(''); const [items,setItems]=useState<{id:string;ticket_number:number;title:string}[]>([]); const {ref,open,setOpen}=useDismissiblePopover(); const search=async(e:FormEvent)=>{e.preventDefault();if(q.trim().length<2){setItems([]);return;}setItems(await request(`/tickets/search?q=${encodeURIComponent(q.trim())}`,actor.session,actor.organizationId) as {id:string;ticket_number:number;title:string}[])}; return <details ref={ref} className="global-search" open={open} onToggle={event=>setOpen(event.currentTarget.open)}><summary aria-label="جست‌وجوی سراسری" title="جست‌وجوی سراسری"><Search size={19}/><span className="sr-only">جست‌وجوی سراسری</span></summary><div className="global-search-panel"><form onSubmit={(e)=>search(e).catch(()=>setItems([]))}><label>عبارت جست‌وجو<input value={q} onChange={e=>setQ(e.target.value)} minLength={2}/></label><button>جست‌وجو</button></form>{items.map(item=><a key={item.id} href="/tickets">#{item.ticket_number} — {item.title}</a>)}</div></details>; }

function AccountMenu({actor,onLogout}:{actor:Actor;onLogout:()=>void}) { const [name,setName]=useState(actor.session.user.displayName); const [currentPassword,setCurrentPassword]=useState(''); const [nextPassword,setNextPassword]=useState(''); const [notice,setNotice]=useState(''); const save=async(e:FormEvent)=>{e.preventDefault();const profile=await request('/auth/profile',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({displayName:name,currentPassword:currentPassword||undefined,nextPassword:nextPassword||undefined})}) as {display_name:string};actor.session.user.displayName=profile.display_name;setCurrentPassword('');setNextPassword('');setNotice(nextPassword?'رمز عبور تغییر کرد؛ برای ورود دوباره آماده شوید.':'پروفایل ذخیره شد.');if(nextPassword)setTimeout(onLogout,700);}; return <details className="account-menu"><summary><CircleUserRound size={18}/>{actor.session.user.displayName}</summary><form autoComplete="off" onSubmit={e=>save(e).catch(c=>setNotice(c instanceof Error?c.message:'خطا در ذخیره'))}><label>نام نمایشی<input value={name} onChange={e=>setName(e.target.value)} autoComplete="name" minLength={2}/></label><label>رمز فعلی<input type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)} autoComplete="current-password" /></label><label>رمز جدید (حداقل ۱۰ نویسه)<input type="password" value={nextPassword} onChange={e=>setNextPassword(e.target.value)} autoComplete="new-password" minLength={nextPassword?10:undefined}/></label><Button type="submit">ذخیره</Button>{notice&&<p className="hint">{notice}</p>}<Button type="button" variant="ghost" onClick={onLogout}><LogOut size={16}/> خروج</Button></form></details>; }

function DashboardHome({ actor, staff }: { actor: Actor; staff: boolean }) { return <DashboardPro actor={actor} staff={staff} />; }
function LegacyDashboardHome({ actor, staff }: { actor: Actor; staff: boolean }) {
  const [tickets, setTickets] = useState<Ticket[]>([]); const [workload, setWorkload] = useState<Record<string, number>>({}); const [platform, setPlatform] = useState<{ organizations: number; active_memberships: number; open_tickets: number } | null>(null); const [error, setError] = useState('');
  useEffect(() => { request('/tickets', actor.session, actor.organizationId).then(setTickets).catch((cause) => setError(cause.message)); if (actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR'].includes(role))) request('/dashboard/workload', actor.session, actor.organizationId).then((rows: { status: string; count: number }[]) => setWorkload(Object.fromEntries(rows.map((row) => [row.status, row.count])))).catch(() => undefined); if (actor.session.user.platformAdmin) request('/dashboard/platform', actor.session, actor.organizationId).then(setPlatform).catch(() => undefined); }, [actor]);
  const active = tickets.filter((ticket) => ['OPEN', 'IN_PROGRESS', 'WAITING_FOR_REQUESTER'].includes(ticket.status)).length;
  const resolved = tickets.filter((ticket) => ['RESOLVED', 'CLOSED'].includes(ticket.status)).length;
  return <section className="page"><div className="page-intro"><div><h2>خوش آمدید</h2><p>نمای کلی کارهای جاری و مسیرهای سریع شما.</p></div><NavLink className="button-link" to="/tickets">ثبت یا مشاهده تیکت‌ها</NavLink></div>{error && <p className="error">{error}</p>}<div className="metric-grid"><Metric label={staff ? 'صف کاری' : 'درخواست‌های من'} value={String(tickets.length)} hint="تیکت‌های قابل مشاهده برای نقش شما" /><Metric label="نیازمند پیگیری" value={String(active)} hint="باز، در حال رسیدگی یا منتظر پاسخ" /><Metric label="حل یا بسته‌شده" value={String(resolved)} hint="تیکت‌های پایان‌یافته" /><Metric label={staff ? 'در حال رسیدگی' : 'باز'} value={String(workload.IN_PROGRESS ?? tickets.filter((ticket) => ticket.status === 'IN_PROGRESS').length)} hint="بر اساس وضعیت فعلی" /></div>{platform && <section className="metric-grid platform-metrics"><Metric label="سازمان‌های فعال" value={String(platform.organizations)} hint="در کل پلتفرم" /><Metric label="عضویت‌های فعال" value={String(platform.active_memberships)} hint="در کل پلتفرم" /><Metric label="تیکت‌های باز پلتفرم" value={String(platform.open_tickets)} hint="محدود به مدیر پلتفرم" /></section>}<section className="card"><h3>شروع سریع</h3><p>از «تیکت‌ها» درخواست جدید ثبت کنید یا تیکت‌های موجود را پیگیری کنید. منو فقط بخش‌هایی را نمایش می‌دهد که نقش شما به آن‌ها دسترسی دارد.</p></section></section>;
}
function Metric({ label, value, hint }: { label: string; value: string; hint: string }) { return <article className="metric-card"><span>{label}</span><strong>{value}</strong><small>{hint}</small></article>; }
function Placeholder({ title, description }: { title: string; description: string }) { return <section className="page"><div className="card empty-state"><h2>{title}</h2><p>{description}</p></div></section>; }
type ReportSummary = { total_tickets: number; active_tickets: number; completed_tickets: number; average_satisfaction: string; sla_breaches: number };
function ReportsPanel({ actor }: { actor: Actor }) { return <ReportsPro actor={actor} />; }
function LegacyReportsPanel({ actor }: { actor: Actor }) { const today = new Date().toISOString().slice(0, 10); const monthAgo = new Date(Date.now() - 29 * 86_400_000).toISOString().slice(0, 10); const [from, setFrom] = useState(monthAgo); const [to, setTo] = useState(today); const [summary, setSummary] = useState<ReportSummary | null>(null); const [error, setError] = useState(''); const query = () => `from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`; const load = () => request(`/reports/summary?${query()}`, actor.session, actor.organizationId).then(setSummary).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [actor.organizationId, actor.session.accessToken]); const exportCsv = async () => { try { const csv = await request(`/reports/export?${query()}`, actor.session, actor.organizationId) as string; const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = `jupiter-report-${from}-to-${to}.csv`; link.click(); URL.revokeObjectURL(url); } catch (cause) { setError(cause instanceof Error ? cause.message : 'خطا در خروجی'); } }; return <section className="page"><div className="page-intro"><div><h2>گزارش‌های عملیاتی</h2><p>نمای سازمانی تیکت، SLA و رضایت در بازهٔ انتخاب‌شده.</p></div><button onClick={exportCsv}>دریافت CSV</button></div><section className="card"><div className="inline-actions"><label>از تاریخ<input aria-label="از تاریخ گزارش" type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></label><label>تا تاریخ<input aria-label="تا تاریخ گزارش" type="date" value={to} onChange={(event) => setTo(event.target.value)} /></label><button className="secondary" onClick={load}>به‌روزرسانی گزارش</button></div></section>{error && <p className="error">{error}</p>}{summary && <div className="metric-grid"><Metric label="کل تیکت‌ها" value={String(summary.total_tickets)} hint={`${from} تا ${to}`}/><Metric label="فعال" value={String(summary.active_tickets)} hint="نیازمند پیگیری"/><Metric label="تکمیل‌شده" value={String(summary.completed_tickets)} hint="حل یا بسته"/><Metric label="رضایت میانگین" value={String(summary.average_satisfaction)} hint={`نقض SLA: ${summary.sla_breaches}`}/></div>}</section>; }
type KnowledgeArticle = { id: string; title: string; body: string; status?: 'DRAFT' | 'IN_REVIEW' | 'PUBLISHED'; created_at?: string };
function KnowledgeSearch({ actor }: { actor: Actor }) { return <KnowledgeWorkspacePro actor={actor} />; }
function LegacyKnowledgeSearch({ actor }: { actor: Actor }) { const [q, setQ] = useState(''); const [items, setItems] = useState<KnowledgeArticle[]>([]); const [title, setTitle] = useState(''); const [body, setBody] = useState(''); const [notice, setNotice] = useState(''); const [reviewVersion, setReviewVersion] = useState(0); const staff = actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR', 'EXPERT'].includes(role)); const reviewer = actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR'].includes(role)); const search = () => request(`/knowledge?q=${encodeURIComponent(q)}`, actor.session, actor.organizationId).then(setItems).catch((cause) => setNotice(cause.message)); useEffect(() => { void search(); }, [actor.organizationId, actor.session.accessToken]); const create = async (event: FormEvent) => { event.preventDefault(); const article = await request('/knowledge', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ title, body }) }) as KnowledgeArticle; await request(`/knowledge/${article.id}/submit-review`, actor.session, actor.organizationId, { method: 'POST' }); setTitle(''); setBody(''); setReviewVersion((version) => version + 1); setNotice('مقاله برای بازبینی ارسال شد.'); }; return <section className="page"><div className="page-intro"><div><h2>دانش‌نامه</h2><p>مقاله‌های منتشرشدهٔ سازمان را جست‌وجو کنید.</p></div></div><div className="admin-grid"><section className="card"><label>جست‌وجو<input value={q} onChange={(event) => setQ(event.target.value)} /></label><button onClick={search}>جست‌وجو</button>{items.length === 0 && <p className="hint">مقالهٔ منتشرشده‌ای پیدا نشد.</p>}{items.map((item) => <article key={item.id}><h3>{item.title}</h3><p>{item.body}</p></article>)}</section>{staff && <form className="card" onSubmit={(event) => create(event).catch((cause) => setNotice(cause.message))}><h3>پیشنهاد مقاله</h3><label>عنوان<input value={title} onChange={(event) => setTitle(event.target.value)} minLength={3} maxLength={200} required /></label><label>متن<textarea value={body} onChange={(event) => setBody(event.target.value)} maxLength={20000} required /></label><button>ارسال برای بازبینی</button>{notice && <p className="hint">{notice}</p>}</form>}</div>{reviewer && <KnowledgeReview actor={actor} refreshVersion={reviewVersion} />}</section>; }
function KnowledgeReview({ actor, refreshVersion }: { actor: Actor; refreshVersion: number }) { const [articles, setArticles] = useState<KnowledgeArticle[]>([]); const [notice, setNotice] = useState(''); const load = () => request('/knowledge/review-queue', actor.session, actor.organizationId).then(setArticles).catch((cause) => setNotice(cause.message)); useEffect(() => { void load(); }, [actor.organizationId, actor.session.accessToken, refreshVersion]); const publish = async (article: KnowledgeArticle) => { await request(`/knowledge/${article.id}/publish`, actor.session, actor.organizationId, { method: 'POST' }); setNotice(`«${article.title}» منتشر شد.`); void load(); }; return <section className="card"><h3>صف بازبینی دانش‌نامه</h3>{notice && <p className="hint">{notice}</p>}{articles.length === 0 && <p className="hint">مقاله‌ای در صف بازبینی نیست.</p>}{articles.map((article) => <article key={article.id}><h4>{article.title}</h4><p>{article.body}</p><p className="hint">وضعیت: {article.status === 'DRAFT' ? 'پیش‌نویس' : 'در انتظار تأیید'}</p>{article.status === 'DRAFT' ? <button className="secondary" onClick={() => request(`/knowledge/${article.id}/submit-review`, actor.session, actor.organizationId, { method: 'POST' }).then(load).catch((cause) => setNotice(cause.message))}>ارسال برای بازبینی</button> : <button onClick={() => publish(article).catch((cause) => setNotice(cause.message))}>انتشار مقاله</button>}</article>)}</section>; }
type AiSetting = { organization_id: string; name: string; slug: string; enabled: boolean; model: string; request_count: number; token_count: number };
type AiAudit = { id: string; organization_name?: string; action: string; target_type: string; created_at: string; actor_display_name?: string };
function PlatformAdministration({ actor }: { actor: Actor }) { return <PlatformPro actor={actor} />; }
function LegacyPlatformAdministration({ actor }: { actor: Actor }) { const [organizations, setOrganizations] = useState<{ id: string; name: string; slug: string; status: string }[]>([]); const [settings, setSettings] = useState<AiSetting[]>([]); const [audit, setAudit] = useState<AiAudit[]>([]); const [error, setError] = useState(''); const load = () => { request('/admin/platform/organizations', actor.session, actor.organizationId).then(setOrganizations).catch((cause) => setError(cause.message)); request('/platform/ai-settings', actor.session, actor.organizationId).then(setSettings).catch((cause) => setError(cause.message)); request('/platform/ai-settings/audit', actor.session, actor.organizationId).then(setAudit).catch((cause) => setError(cause.message)); }; useEffect(() => { void load(); }, [actor.organizationId, actor.session.accessToken]); const toggle = async (organization: { id: string; status: string }) => { try { await request(`/admin/platform/organizations/${organization.id}/status`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ status: organization.status === 'active' ? 'suspended' : 'active' }) }); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'خطا در تغییر وضعیت'); } }; const saveAi = async (setting: AiSetting, enabled: boolean, model: string) => { try { await request('/platform/ai-settings', actor.session, actor.organizationId, { method: 'PUT', body: JSON.stringify({ organizationId: setting.organization_id, enabled, model }) }); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'خطا در ذخیرهٔ سیاست AI'); } }; return <section className="page"><h2>مدیریت پلتفرم</h2>{error && <p className="error">{error}</p>}<section className="card"><h3>سازمان‌ها</h3>{organizations.map((organization) => <p key={organization.id}><strong>{organization.name}</strong> — {organization.slug} — {organization.status} <button className="secondary" onClick={() => toggle(organization)}>{organization.status === 'active' ? 'تعلیق' : 'فعال‌سازی'}</button></p>)}</section><section className="card"><h3>سیاست و مصرف هوش مصنوعی</h3><p className="hint">فقط مدیر پلتفرم می‌تواند دسترسی AI سازمان‌ها را فعال کند. هر پیشنهاد قبل از اعمال نیازمند تأیید کاربر است.</p>{settings.map((setting) => <AiSettingRow key={setting.organization_id} setting={setting} onSave={saveAi} />)}</section><section className="card"><h3>ردپای قابل بازبینی AI و تبدیل صوت</h3>{audit.length === 0 && <p className="hint">رویدادی ثبت نشده است.</p>}{audit.map((item) => <p key={item.id}><strong>{item.action}</strong> — {item.organization_name ?? 'پلتفرم'} — {item.actor_display_name ?? 'سامانه'} — {new Date(item.created_at).toLocaleString('fa-IR')}</p>)}</section></section>; }
function AiSettingRow({ setting, onSave }: { setting: AiSetting; onSave: (setting: AiSetting, enabled: boolean, model: string) => Promise<void> }) { const [enabled, setEnabled] = useState(setting.enabled); const [model, setModel] = useState(setting.model); useEffect(() => { setEnabled(setting.enabled); setModel(setting.model); }, [setting]); return <article><h4>{setting.name}</h4><p className="hint">{setting.request_count} درخواست · {setting.token_count} توکن ثبت‌شده</p><label><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /> فعال‌سازی AI برای این سازمان</label><label>مدل<input aria-label={`مدل AI ${setting.name}`} value={model} onChange={(event) => setModel(event.target.value)} maxLength={120} /></label><button className="secondary" onClick={() => onSave(setting, enabled, model)}>ذخیرهٔ سیاست AI</button></article>; }
function AdminPage({ actor }: { actor: Actor }) { return <OrganizationAdminConsole actor={actor} />; }
function LegacyAdminPage({ actor }: { actor: Actor }) { const [members,setMembers]=useState<{id:string;display_name:string;email:string;roles:string[]}[]>([]); const [templates,setTemplates]=useState<{id:string;name:string;body:string}[]>([]); const [policy,setPolicy]=useState('STAFF_ONLY'); const [templateName,setTemplateName]=useState(''); const [templateBody,setTemplateBody]=useState(''); const [error,setError]=useState(''); const load=()=>{request('/admin/members',actor.session,actor.organizationId).then(setMembers).catch(e=>setError(e.message));request('/admin/templates',actor.session,actor.organizationId).then(setTemplates).catch(e=>setError(e.message));request('/admin/settings',actor.session,actor.organizationId).then((s:{closure_policy:string})=>setPolicy(s.closure_policy)).catch(e=>setError(e.message));}; useEffect(load,[actor]); const savePolicy=async()=>{try{await request('/admin/settings',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({closurePolicy:policy,reopenWindowDays:7,businessTimezone:'Asia/Tehran'})})}catch(e){setError(e instanceof Error?e.message:'خطا')}}; const saveTemplate=async(e:FormEvent)=>{e.preventDefault();try{await request('/admin/templates',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({name:templateName,body:templateBody})});setTemplateName('');setTemplateBody('');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}}; return <section className="page"><h2>مدیریت سازمان</h2>{error&&<p className="error">{error}</p>}<div className="admin-grid"><section className="card"><h3>اعضای سازمان</h3>{members.map(m=><p key={m.id}><strong>{m.display_name}</strong> — {m.email} — {(m.roles??[]).join('، ')}</p>)}</section><section className="card"><h3>سیاست بستن تیکت</h3><select aria-label="سیاست بستن" value={policy} onChange={e=>setPolicy(e.target.value)}><option value="STAFF_ONLY">فقط کارکنان</option><option value="REQUESTER_CONFIRMATION">تایید درخواست‌کننده</option><option value="AUTO_EXPIRE">بستن خودکار</option></select><button onClick={savePolicy}>ذخیره سیاست</button></section><section className="card"><h3>قالب پاسخ</h3><form onSubmit={saveTemplate}><label>نام<input value={templateName} onChange={e=>setTemplateName(e.target.value)} required/></label><label>متن<textarea value={templateBody} onChange={e=>setTemplateBody(e.target.value)} required/></label><button>ذخیره قالب</button></form>{templates.map(t=><p key={t.id}><strong>{t.name}</strong> — {t.body}</p>)}</section></div><SlaAdministration actor={actor}/></section>; }

function SlaAdministration({actor}:{actor:Actor}) { const [policies,setPolicies]=useState<{id:string;name:string;priority:string;first_response_minutes:number;resolution_minutes:number;warning_minutes:number;escalation_role:string}[]>([]); const [calendar,setCalendar]=useState({timezone:'Asia/Tehran',workdays:[1,2,3,4,5],startMinute:480,endMinute:1020}); const [clocks,setClocks]=useState<{id:string;ticket_number:number;title:string;resolution_due_at:string;warning_at?:string;breached_at?:string}[]>([]); const [form,setForm]=useState({name:'پاسخ استاندارد',priority:'NORMAL',firstResponseMinutes:60,resolutionMinutes:480,warningMinutes:30,escalationRole:'SUPERVISOR'}); const [notice,setNotice]=useState(''); const load=()=>{request('/sla/policies',actor.session,actor.organizationId).then(setPolicies).catch(e=>setNotice(e.message));request('/sla/calendar',actor.session,actor.organizationId).then((value:{timezone:string;workdays:number[];start_minute:number;end_minute:number})=>setCalendar({timezone:value.timezone,workdays:value.workdays,startMinute:value.start_minute,endMinute:value.end_minute})).catch(()=>undefined);request('/sla/clocks',actor.session,actor.organizationId).then(setClocks).catch(()=>undefined);};useEffect(load,[actor.organizationId]);const savePolicy=async(e:FormEvent)=>{e.preventDefault();await request('/sla/policies',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify(form)});setNotice('سیاست SLA ذخیره شد.');load();};const saveCalendar=async(e:FormEvent)=>{e.preventDefault();await request('/sla/calendar',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify(calendar)});setNotice('تقویم کاری ذخیره شد.');};return <section className="page"><h2>مدیریت SLA و اتوماسیون</h2>{notice&&<p className="hint">{notice}</p>}<div className="admin-grid"><section className="card"><h3>سیاست SLA</h3><form onSubmit={e=>savePolicy(e).catch(c=>setNotice(c.message))}><label>نام<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></label><label>اولویت<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{['LOW','NORMAL','HIGH','URGENT'].map(value=><option key={value}>{value}</option>)}</select></label><label>پاسخ اول (دقیقه)<input type="number" min="1" value={form.firstResponseMinutes} onChange={e=>setForm({...form,firstResponseMinutes:Number(e.target.value)})}/></label><label>حل مسئله (دقیقه)<input type="number" min="1" value={form.resolutionMinutes} onChange={e=>setForm({...form,resolutionMinutes:Number(e.target.value)})}/></label><label>هشدار قبل از سررسید (دقیقه)<input type="number" min="1" value={form.warningMinutes} onChange={e=>setForm({...form,warningMinutes:Number(e.target.value)})}/></label><label>تشدید به<select value={form.escalationRole} onChange={e=>setForm({...form,escalationRole:e.target.value})}><option value="SUPERVISOR">سرپرست</option><option value="ORG_ADMIN">مدیر سازمان</option></select></label><button>ذخیرهٔ سیاست</button></form>{policies.map(policy=><p key={policy.id}><strong>{policy.priority}</strong> — {policy.first_response_minutes}/{policy.resolution_minutes} دقیقه — هشدار {policy.warning_minutes} دقیقه</p>)}</section><section className="card"><h3>تقویم کاری</h3><form onSubmit={e=>saveCalendar(e).catch(c=>setNotice(c.message))}><label>منطقهٔ زمانی<input value={calendar.timezone} onChange={e=>setCalendar({...calendar,timezone:e.target.value})}/></label><label>شروع روز کاری (دقیقه از نیمه‌شب)<input type="number" min="0" max="1439" value={calendar.startMinute} onChange={e=>setCalendar({...calendar,startMinute:Number(e.target.value)})}/></label><label>پایان روز کاری (دقیقه از نیمه‌شب)<input type="number" min="1" max="1440" value={calendar.endMinute} onChange={e=>setCalendar({...calendar,endMinute:Number(e.target.value)})}/></label><button>ذخیرهٔ تقویم</button></form><p className="hint">روزهای کاری پیش‌فرض: شنبه تا چهارشنبه. ساعت‌ها به دقیقه از نیمه‌شب وارد می‌شوند.</p></section></div><section className="card"><h3>پایش SLA</h3>{clocks.map(clock=><p key={clock.id}><strong>#{clock.ticket_number} {clock.title}</strong> — سررسید: {clock.resolution_due_at?new Date(clock.resolution_due_at).toLocaleString('fa-IR'):'—'} {clock.breached_at?'· نقض شده':clock.warning_at?'· هشدار ارسال شده':''}</p>)}{clocks.length===0&&<p>ساعت SLA فعالی وجود ندارد.</p>}</section></section>; }

function TicketWorkspace({ actor, staff }: { actor: Actor; staff: boolean }) { return <TicketWorkspacePro actor={actor} staff={staff} />; }
function LegacyTicketWorkspace({ actor, staff }: { actor: Actor; staff: boolean }) {
  const manager = actor.membership.role_codes.some((role) => ['ORG_ADMIN', 'SUPERVISOR'].includes(role));
  const [tickets, setTickets] = useState<Ticket[]>([]); const [selected, setSelected] = useState<Ticket | null>(null); const [error, setError] = useState(''); const [refresh, setRefresh] = useState(0);
  const [status, setStatus] = useState(''); const [priority, setPriority] = useState(''); const [query, setQuery] = useState(''); const [sort, setSort] = useState('newest'); const [checked, setChecked] = useState<string[]>([]);
  const load = () => { const params = new URLSearchParams(); if(status) params.set('status',status); if(priority) params.set('priority',priority); if(query.trim()) params.set('q',query.trim()); if(sort !== 'newest') params.set('sort',sort); request(`/tickets?${params}`, actor.session, actor.organizationId).then((items:Ticket[]) => { setTickets(items); setChecked((ids) => ids.filter((id) => items.some((ticket) => ticket.id === id))); }).catch((cause) => setError(cause.message)); };
  useEffect(() => { setSelected(null); load(); }, [actor.organizationId, refresh, status, priority, sort]);
  const saveView = () => { sessionStorage.setItem(`jupiter.view.${actor.organizationId}`, JSON.stringify({status,priority,query,sort})); };
  const restoreView = () => { const stored = sessionStorage.getItem(`jupiter.view.${actor.organizationId}`); if(stored) { const view = JSON.parse(stored) as {status?:string;priority?:string;query?:string;sort?:string}; setStatus(view.status ?? ''); setPriority(view.priority ?? ''); setQuery(view.query ?? ''); setSort(view.sort ?? 'newest'); } };
  const bulk = async (next: string) => { try { await request('/tickets/bulk/status',actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({ticketIds:checked,status:next})}); setChecked([]); setRefresh((value)=>value+1); } catch (cause) { setError(cause instanceof Error ? cause.message : 'عملیات گروهی ناموفق بود.'); } };
  return <section className="ticket-workspace"><aside className="card sidebar"><div className="section-heading"><h2>فضای کاری تیکت‌ها</h2><button className="secondary" onClick={() => setRefresh((value) => value + 1)}>تازه‌سازی</button></div><p>{staff ? 'صف تیکت‌های مجاز شما' : 'درخواست‌های ثبت‌شده شما'}</p><div className="workspace-filters"><label>جست‌وجو<input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')load();}} placeholder="عنوان تیکت"/></label><button className="secondary" onClick={load}>اعمال</button><label>وضعیت<select value={status} onChange={e=>setStatus(e.target.value)}><option value="">همه</option><option value="OPEN">باز</option><option value="IN_PROGRESS">در حال رسیدگی</option><option value="WAITING_FOR_REQUESTER">منتظر پاسخ</option><option value="RESOLVED">حل‌شده</option><option value="CLOSED">بسته</option></select></label><label>اولویت<select value={priority} onChange={e=>setPriority(e.target.value)}><option value="">همه</option><option value="URGENT">فوری</option><option value="HIGH">بالا</option><option value="NORMAL">عادی</option><option value="LOW">کم</option></select></label><label>مرتب‌سازی<select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">جدیدترین</option><option value="oldest">قدیمی‌ترین</option><option value="priority">اولویت</option></select></label><div className="inline-actions"><button className="secondary" onClick={saveView}>ذخیرهٔ نما</button><button className="secondary" onClick={restoreView}>بازیابی نما</button></div></div>{manager && checked.length > 0 && <div className="bulk-actions"><span>{checked.length} انتخاب شده</span><button onClick={()=>bulk('IN_PROGRESS')}>شروع رسیدگی گروهی</button><button className="secondary" onClick={()=>bulk('RESOLVED')}>حل گروهی</button></div>}{tickets.map((ticket) => <div className={`ticket-row ${selected?.id === ticket.id ? 'active' : ''}`} key={ticket.id}>{manager && <input aria-label={`انتخاب تیکت ${ticket.ticket_number}`} type="checkbox" checked={checked.includes(ticket.id)} onChange={e=>setChecked(ids=>e.target.checked?[...ids,ticket.id]:ids.filter(id=>id!==ticket.id))}/>}<button className="ticket" onClick={() => setSelected(ticket)}><strong>#{ticket.ticket_number} · {ticket.title}</strong><span>{ticket.status} · {ticket.priority}{ticket.assignee_display_name ? ` · ${ticket.assignee_display_name}` : ''}</span>{ticket.tags?.length ? <span className="tag-list">{ticket.tags.map(tag=><i key={tag.id} style={{backgroundColor:tag.color}}>{tag.name}</i>)}</span> : null}</button></div>)}{tickets.length === 0 && <p>تیکتی با این معیارها وجود ندارد.</p>}</aside><section className="card content">{error && <p className="error">{error}</p>}{selected ? <TicketPanel actor={actor} ticket={selected} staff={staff} manager={manager} onRefresh={() => setRefresh((value) => value + 1)} /> : <NewTicket actor={actor} onCreated={() => setRefresh((value) => value + 1)} />}</section></section>;
}
function NewTicket({ actor, onCreated }: { actor: Actor; onCreated: () => void }) { const [title, setTitle] = useState(''); const [description, setDescription] = useState(''); const [notice, setNotice] = useState(''); async function submit(event: FormEvent) { event.preventDefault(); const draft = await request('/tickets/drafts', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ title, description }) }); await request(`/tickets/${draft.id}/submit`, actor.session, actor.organizationId, { method: 'POST' }); setNotice('تیکت با موفقیت ثبت شد.'); setTitle(''); setDescription(''); onCreated(); } return <><h2>ثبت درخواست جدید</h2><form onSubmit={(event) => submit(event).catch((cause) => setNotice(cause.message))}><label>عنوان<input value={title} onChange={(e) => setTitle(e.target.value)} minLength={3} required /></label><label>شرح درخواست<textarea value={description} onChange={(e) => setDescription(e.target.value)} required /></label><button>ثبت و ارسال</button>{notice && <p>{notice}</p>}</form></>; }
const ticketStatusLabel: Record<string,string> = { DRAFT:'پیش‌نویس',OPEN:'باز',IN_PROGRESS:'در حال رسیدگی',WAITING_FOR_REQUESTER:'منتظر پاسخ درخواست‌کننده',RESOLVED:'حل‌شده',CLOSED:'بسته' };
const ticketPriorityLabel: Record<string,string> = { LOW:'کم',NORMAL:'عادی',HIGH:'بالا',URGENT:'فوری' };
const activityLabel: Record<string,string> = { 'ticket.draft_created':'پیش‌نویس ایجاد شد','ticket.status_changed':'وضعیت تیکت تغییر کرد','ticket.auto_assigned':'واگذاری خودکار انجام شد','ticket.assigned':'مسئول تیکت تعیین شد','ticket.tagged':'برچسب افزوده شد','ticket.attachment_available':'پیوست در دسترس است','ticket.email_received':'درخواست از ایمیل دریافت شد' };

function TicketPanel({ actor, ticket, staff, manager, onRefresh }: { actor: Actor; ticket: Ticket; staff: boolean; manager: boolean; onRefresh: () => void }) {
  const [messages, setMessages] = useState<Message[]>([]); const [assignees, setAssignees] = useState<{ id: string; display_name: string }[]>([]); const [tags, setTags] = useState<TicketTag[]>([]); const [assignee, setAssignee] = useState(ticket.assigned_to_user_id ?? ''); const [tagId, setTagId] = useState(''); const [tagName, setTagName] = useState(''); const [body, setBody] = useState(''); const [notice, setNotice] = useState('');
  const load = () => request(`/tickets/${ticket.id}/messages`, actor.session, actor.organizationId).then(setMessages).catch((cause) => setNotice(cause.message));
  const loadTags = () => request('/tickets/tags', actor.session, actor.organizationId).then(setTags).catch(() => undefined);
  useEffect(() => { void load(); if (manager) { void request('/tickets/assignees', actor.session, actor.organizationId).then(setAssignees); void loadTags(); } }, [ticket.id, manager]);
  const status = async (next: string) => { await request(`/tickets/${ticket.id}/status`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ status: next }) }); setNotice('وضعیت تیکت به‌روزرسانی شد.'); onRefresh(); };
  const assign = async () => { if (!assignee) return; await request(`/tickets/${ticket.id}/assignment`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ assignedToUserId: assignee }) }); setNotice('مسئول تیکت تعیین شد.'); onRefresh(); };
  const addTag = async () => { if (!tagId) return; await request(`/tickets/${ticket.id}/tags/${tagId}`, actor.session, actor.organizationId, { method: 'POST' }); setNotice('برچسب افزوده شد.'); onRefresh(); };
  const createTag = async () => { if (tagName.trim().length < 2) return; const tag = await request('/tickets/tags', actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ name: tagName.trim() }) }) as TicketTag; setTagId(tag.id); setTagName(''); await loadTags(); setNotice('برچسب جدید ساخته شد.'); };
  const watch = async () => { await request(`/tickets/${ticket.id}/watch`, actor.session, actor.organizationId, { method: 'POST' }); setNotice('این تیکت در فهرست پیگیری شما قرار گرفت.'); };
  const statusActions = ticket.status === 'RESOLVED' ? <><button className="secondary" onClick={() => status('CLOSED')}>تأیید و بستن</button><button className="secondary" onClick={() => status('OPEN')}>بازگشایی</button></> : ticket.status === 'CLOSED' ? <button className="secondary" onClick={() => status('OPEN')}>بازگشایی</button> : staff ? <><button className="secondary" onClick={() => status('IN_PROGRESS')}>شروع رسیدگی</button><button className="secondary" onClick={() => status('RESOLVED')}>حل شد</button></> : null;
  return <><div className="ticket-heading"><div><p className="eyebrow">#{ticket.ticket_number} · {ticketStatusLabel[ticket.status] ?? 'نامشخص'}</p><h2>{ticket.title}</h2><p className="hint">اولویت: {ticketPriorityLabel[ticket.priority] ?? 'نامشخص'} {ticket.assignee_display_name ? `· مسئول: ${ticket.assignee_display_name}` : '· بدون مسئول'}</p></div><div className="actions">{statusActions}{staff && <button className="secondary" onClick={() => void watch()}>پیگیری</button>}</div></div>{manager && <section className="ticket-tools"><label>واگذاری<select value={assignee} onChange={(event) => setAssignee(event.target.value)}><option value="">یک کارشناس انتخاب کنید</option>{assignees.map((person) => <option key={person.id} value={person.id}>{person.display_name}</option>)}</select></label><button onClick={() => void assign()}>ثبت واگذاری</button><label>برچسب<select value={tagId} onChange={(event) => setTagId(event.target.value)}><option value="">یک برچسب انتخاب کنید</option>{tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select></label><button className="secondary" onClick={() => void addTag()}>افزودن برچسب</button><label>برچسب جدید<input value={tagName} onChange={(event) => setTagName(event.target.value)} placeholder="مثلاً فوری" /></label><button className="secondary" onClick={() => void createTag()}>ساخت برچسب</button></section>}{!staff && <AiAssistant actor={actor} ticket={ticket} onRefresh={onRefresh} />}<CollaborationPanel actor={actor} ticket={ticket} staff={staff} onRefresh={onRefresh}/><form className="message-composer" onSubmit={(event) => { event.preventDefault(); request(`/tickets/${ticket.id}/messages`, actor.session, actor.organizationId, { method: 'POST', body: JSON.stringify({ body }) }).then(() => { setBody(''); void load(); onRefresh(); }).catch((cause) => setNotice(cause.message)); }}><label>ارسال پیام جدید<textarea value={body} onChange={(event) => setBody(event.target.value)} required /></label><button>ارسال پیام</button></form>{notice && <p>{notice}</p>}</>;
}

function CollaborationPanel({actor,ticket,staff,onRefresh}:{actor:Actor;ticket:Ticket;staff:boolean;onRefresh:()=>void}) { const [timeline,setTimeline]=useState<{id:string;kind:string;activity_type?:string;author_display_name?:string;body?:string;created_at:string}[]>([]); const [notes,setNotes]=useState<{id:string;author_display_name:string;body:string;created_at:string}[]>([]); const [attachments,setAttachments]=useState<{id:string;original_filename:string;byte_size:number;created_at:string}[]>([]); const [note,setNote]=useState(''); const [score,setScore]=useState('5'); const [ratingComment,setRatingComment]=useState(''); const [notice,setNotice]=useState(''); const [uploading,setUploading]=useState(''); const load=()=>{request(`/tickets/${ticket.id}/timeline`,actor.session,actor.organizationId).then(setTimeline).catch(e=>setNotice(e.message)); request(`/tickets/${ticket.id}/attachments`,actor.session,actor.organizationId).then(setAttachments).catch(()=>undefined); if(staff)request(`/tickets/${ticket.id}/notes`,actor.session,actor.organizationId).then(setNotes).catch(()=>undefined);}; useEffect(()=>{load();},[ticket.id,staff]); const addNote=async(e:FormEvent)=>{e.preventDefault();await request(`/tickets/${ticket.id}/notes`,actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({body:note})});setNote('');load();}; const rate=async(e:FormEvent)=>{e.preventDefault();await request(`/tickets/${ticket.id}/rating`,actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({score:Number(score),comment:ratingComment})});setNotice('امتیاز شما ثبت شد.');setRatingComment('');}; const upload=async(e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;setUploading(file.name);setNotice('آماده‌سازی بارگذاری…');try{const response=await request(`/tickets/${ticket.id}/attachments/upload-requests`,actor.session,actor.organizationId,{method:'POST',body:JSON.stringify({filename:file.name,contentType:file.type,byteSize:file.size})}) as {attachment:{id:string};uploadUrl:string};setNotice('در حال بارگذاری امن فایل…');const put=await fetch(response.uploadUrl,{method:'PUT',headers:{'content-type':file.type},body:file});if(!put.ok)throw new Error('بارگذاری فایل ناموفق بود.');await request(`/tickets/${ticket.id}/attachments/${response.attachment.id}/complete`,actor.session,actor.organizationId,{method:'POST'});setNotice('پیوست با موفقیت افزوده شد.');load();}catch(cause){setNotice(cause instanceof Error?cause.message:'خطا در بارگذاری فایل');}finally{setUploading('');e.target.value='';}}; const download=async(id:string)=>{const result=await request(`/tickets/${ticket.id}/attachments/${id}/download`,actor.session,actor.organizationId) as {downloadUrl:string};window.open(result.downloadUrl,'_blank','noopener,noreferrer');}; return <section className="collaboration"><div className="collaboration-grid"><section><h3>تاریخچهٔ یکپارچه</h3><div className="timeline">{timeline.map(item=><article key={`${item.kind}-${item.id}`}><strong>{item.kind==='note'?'یادداشت داخلی':item.kind==='message'?(item.author_display_name??'پیام'):(activityLabel[item.activity_type??'']??'رویداد سیستمی')}</strong>{item.body&&<p>{item.body}</p>}<small>{new Date(item.created_at).toLocaleString('fa-IR')}</small></article>)}{timeline.length===0&&<p className="hint">هنوز رویدادی ثبت نشده است.</p>}</div></section><section><h3>پیوست‌ها</h3><label className="file-input">افزودن فایل<input type="file" onChange={upload} disabled={Boolean(uploading)}/></label>{uploading&&<p className="hint" role="status">در حال بارگذاری: {uploading}</p>}{attachments.map(file=><p key={file.id}><button className="secondary" onClick={()=>download(file.id)}>{file.original_filename}</button> <small>{Math.ceil(Number(file.byte_size)/1024)} KB</small></p>)}</section></div>{staff&&<section className="internal-notes"><h3>یادداشت داخلی</h3>{notes.map(item=><article key={item.id}><strong>{item.author_display_name}</strong><p>{item.body}</p></article>)}<form onSubmit={e=>addNote(e).catch(c=>setNotice(c.message))}><label>یادداشت فقط برای کارکنان<textarea value={note} onChange={e=>setNote(e.target.value)} required/></label><button className="secondary">ثبت یادداشت</button></form></section>}{!staff&&['RESOLVED','CLOSED'].includes(ticket.status)&&<form className="rating-form" onSubmit={e=>rate(e).catch(c=>setNotice(c.message))}><h3>ارزیابی رسیدگی</h3><label>امتیاز<select value={score} onChange={e=>setScore(e.target.value)}>{[5,4,3,2,1].map(value=><option key={value} value={value}>{value} از ۵</option>)}</select></label><label>نظر شما<textarea value={ratingComment} onChange={e=>setRatingComment(e.target.value)}/></label><button>ثبت ارزیابی</button></form>}{notice&&<p className="hint" role="status">{notice}</p>}</section>; }
